import {mkdtemp,writeFile,readFile,rm} from 'node:fs/promises';import {join} from 'node:path';import {tmpdir} from 'node:os';
export async function participationEgo(t,baseUrl,{action='register',human='',broken=false,token='ego-fixture-token',selected=false,file=false,unrelated=false,preparationToken}={}){
 const root=await mkdtemp(join(tmpdir(),'friends-org-ego-'));t.after(()=>rm(root,{recursive:true,force:true}));
 const html=action==='register'?`<div class="main"><div class="form-container"><div class="form-title small-title">1.参与说明</div><div class="form-content"><textarea>${human}</textarea></div></div>${broken?'':`<div class="form-container"><div class="form-title small-title">2.协作方式</div><div class="form-content"><div class="van-cell"><span class="van-cell__title">布置</span><div role="checkbox" aria-checked="${selected}"></div></div><div class="van-cell"><span class="van-cell__title">协作</span><div role="checkbox" aria-checked="false"></div></div></div></div>`}${file?'<input id="material" type="file">':''}<button class="bot_btn">申请加入</button></div><script>${file?'Object.defineProperty(document.querySelector("#material"),"files",{value:[new File(["human"],"human.pdf")]});':''}document.querySelectorAll('[role=checkbox]').forEach(e=>e.onclick=()=>e.setAttribute('aria-checked',String(e.getAttribute('aria-checked')!=='true')));document.querySelector('.bot_btn').onclick=()=>fetch('/business/register',{method:'POST'});</script>`:`<div class="list-group"><div class="title">示例组织活动</div><div class="list-action"><div id="exit"><span>退出报名</span></div></div></div><div class="van-dialog" style="display:none"><div class="van-dialog__header">退出确认</div><button id="final">确认</button></div><script>document.querySelector('#exit').onclick=()=>document.querySelector('.van-dialog').style.display='block';document.querySelector('#final').onclick=()=>fetch('/business/exit',{method:'POST'});</script>`;
 const path=join(root,'page.html'),config=join(root,'config.json'),result=join(root,'result.json');await writeFile(path,html);await writeFile(config,JSON.stringify({html:path,result,frame:true,token,preparationToken,outerUrl:baseUrl.replace('/gateway','')+'/mobile/main/index',url:baseUrl.replace('/gateway','')+(action==='register'?'/mobile/acManage/stuActivityApplyDetail?pageType=JOIN&uuid='+(unrelated?'other-activity':'org-activity-1'):'/mobile/acManage/stuActivityApplyList')}));const command=join(root,'ego-browser');await writeFile(command,`#!/bin/sh\nFRIENDS_EGO_FIXTURE_CONFIG='${config}' exec '${process.execPath}' '${join(process.cwd(),'tests/fixtures/strict-ego.mjs')}'\n`,{mode:0o700});return {command,root,observed:async()=>JSON.parse(await readFile(result,'utf8'))};
}
